// offline_first_aid_data.dart
// 30+ first-aid topics × 10 languages
// Languages: en, hi, te, ta, ar, es, fr, pt, de, zh
//
// Usage:
//   final answer = OfflineFirstAidData.find(
//     query: userText,
//     langCode: AppLocalizations.of(context).locale.languageCode,
//   );

class OfflineFirstAidData {
  // ─── Public API ────────────────────────────────────────────────────────────

  /// Returns the best-matching offline first-aid answer in the given language.
  /// Falls back to a generic message if no topic matches.
  static String find({required String query, required String langCode}) {
    final q = query.toLowerCase();
    for (final topic in _topics) {
      for (final kw in topic.keywords) {
        if (q.contains(kw)) {
          return topic.answer(langCode);
        }
      }
    }
    return _generic(langCode);
  }

