  // ─── Topics ────────────────────────────────────────────────────────────────
  static final List<_Topic> _topics = [

    // 1. BLEEDING
    _Topic(
      keywords: ['bleeding', 'bleed', 'blood', 'खून', 'रक्त', 'రక్తం', 'இரத்தம்', 'نزيف', 'sangrado', 'saignement', 'sangramento', 'blutung', 'ರಕ್ತ'],
      answers: {
        'en': '🩸 SEVERE BLEEDING\n\n1. CALL 108/112 immediately.\n2. Apply firm, direct pressure with a clean cloth.\n3. Do NOT remove the cloth — add more on top if soaked.\n4. Elevate the injured limb above heart level if possible.\n5. If a limb and bleeding won\'t stop, apply tourniquet 5–7 cm above wound; note the time.\n6. Keep person warm and calm.\n\n❌ Do NOT use tourniquet on neck, chest, or abdomen.\n❌ Do NOT probe or remove embedded objects.',
        'hi': '🩸 गंभीर रक्तस्राव\n\n1. तुरंत 108/112 पर कॉल करें।\n2. साफ कपड़े से मजबूत, सीधा दबाव लगाएँ।\n3. कपड़ा न हटाएँ — भीग जाए तो ऊपर से और लगाएँ।\n4. संभव हो तो घायल अंग को हृदय से ऊपर उठाएँ।\n5. अंग से रक्त न रुके तो घाव से 5–7 सेमी ऊपर टूर्निकेट लगाएँ; समय नोट करें।\n6. व्यक्ति को गर्म व शांत रखें।\n\n❌ गर्दन, छाती या पेट पर टूर्निकेट न लगाएँ।\n❌ धँसी वस्तु न छेड़ें और न निकालें।',
        'te': '🩸 తీవ్రమైన రక్తస్రావం\n\n1. వెంటనే 108/112 కి కాల్ చేయండి.\n2. శుభ్రమైన గుడ్డతో గట్టి, నేరుగా ఒత్తిడి వేయండి.\n3. గుడ్డ తొలగించవద్దు — తడిసిపోతే పైన మరింత వేయండి.\n4. సాధ్యమైతే గాయపడిన అంగాన్ని గుండె స్థాయికి పైగా పైకెత్తండి.\n5. అంగంలో రక్తం ఆగకపోతే గాయానికి 5–7 సెమీ పైన టూర్నికే వేయండి; సమయం గుర్తించండి.\n6. వ్యక్తిని వెచ్చగా, శాంతంగా ఉంచండి.\n\n❌ మెడ, ఛాతీ లేదా పొట్టపై టూర్నికే వేయవద్దు.\n❌ లోపల దిగబడిన వస్తువులను తీయవద్దు.',
        'ta': '🩸 கடுமையான இரத்தப்போக்கு\n\n1. உடனடியாக 108/112 ஐ அழையுங்கள்.\n2. சுத்தமான துணியால் நேரடி அழுத்தம் கொடுங்கள்.\n3. துணியை அகற்றாதீர்கள் — நனைந்தால் மேலும் சேர்க்கவும்.\n4. முடிந்தால் காயமடைந்த உறுப்பை இதயத்திற்கு மேலே உயர்த்துங்கள்.\n5. உறுப்பில் இரத்தம் நிற்கவில்லையெனில் காயத்திற்கு 5–7 செமீ மேலே தூர்னிக்கே போடுங்கள்; நேரத்தை குறிக்கவும்.\n6. நபரை சூடாகவும் அமைதியாகவும் வையுங்கள்.\n\n❌ கழுத்து, மார்பு அல்லது வயிற்றில் தூர்னிக்கே போடாதீர்கள்.\n❌ உள்ளே நுழைந்த பொருட்களை அகற்றாதீர்கள்.',
        'ar': '🩸 نزيف حاد\n\n1. اتصل بـ 108/112 فوراً.\n2. اضغط بشكل مباشر وقوي بقطعة قماش نظيفة.\n3. لا تُزِل القماش — إذا نقعت أضف المزيد فوقها.\n4. ارفع الطرف المصاب فوق مستوى القلب إن أمكن.\n5. إذا لم يتوقف النزيف في الطرف، ضع عاصبة 5–7 سم فوق الجرح وسجّل الوقت.\n6. أبقِ الشخص دافئاً وهادئاً.\n\n❌ لا تضع العاصبة على الرقبة أو الصدر أو البطن.\n❌ لا تتلمّس أو تُخرج الأجسام الغريبة المغروزة.',
